package main

import (
	"fmt"
	"html"
	"html/template"
)

func getWelcomeMessage(username string) string {
	// Sanitize the username to prevent XSS
	sanitizedUsername := html.EscapeString(username)
	return "<p>Welcome, " + sanitizedUsername + "!</p>"
}

func main() {
	// Example usage
	fmt.Println(getWelcomeMessage("<script>alert('XSS')</script>"))
}

